function distanceKm(a,b){const R=6371,r=v=>v*Math.PI/180,dLat=r(b.lat-a.lat),dLng=r(b.lng-a.lng),x=Math.sin(dLat/2)**2+Math.cos(r(a.lat))*Math.cos(r(b.lat))*Math.sin(dLng/2)**2;return R*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}
function jobDistance(j){return distanceKm(userLocation,{lat:j.lat,lng:j.lng})}
function estimateTravel(j){const km=jobDistance(j)*1.25,modes={walk:{speed:4.5,extra:0,label:'pieszo'},bike:{speed:15,extra:2,label:'rowerem'},transit:{speed:18,extra:8,label:'komunikacją'},car:{speed:28,extra:5,label:'samochodem'}},m=modes[travelMode];return{minutes:Math.max(3,Math.round(km/m.speed*60+m.extra)),label:m.label}}
function timeMatches(j){return filters.time==='all'||(filters.time==='morning'&&j.start<12)||(filters.time==='afternoon'&&j.start>=12&&j.start<17)||(filters.time==='evening'&&j.start>=17)}
function jobIsTaken(j){return applications.some(a=>a.jobId===j.id&&['confirmed','completed','employer_issue'].includes(a.status))}
function nextShiftDate(j){const dayNumbers={monday:1,tuesday:2,wednesday:3,thursday:4,friday:5,saturday:6,sunday:0},now=new Date(),target=dayNumbers[j.day]??now.getDay(),date=new Date(now);date.setHours(Math.floor(j.start),Math.round(j.start%1*60),0,0);let add=(target-now.getDay()+7)%7;if(add===0&&date<=now)add=7;date.setDate(date.getDate()+add);return date}
function offerDeadline(j){const date=nextShiftDate(j);date.setHours(date.getHours()-(j.applicationLeadHours??2));if(date<=new Date())date.setDate(date.getDate()+7);return date}
function cancellationPolicyFor(job){const hoursUntil=(nextShiftDate(job)-Date.now())/3600000;return{adHoc:hoursUntil<=8,hoursUntil}}
function offerDeadlineLabel(j){const deadline=offerDeadline(j),left=Math.max(0,deadline-Date.now()),minutes=Math.floor(left/60000),days=Math.floor(minutes/1440),hours=Math.floor(minutes%1440/60),mins=minutes%60,remaining=days?`${days} d ${hours} godz.`:hours?`${hours} godz. ${mins} min`:`${Math.max(0,mins)} min`,date=new Intl.DateTimeFormat(currentLanguage==='en'?'en-GB':'pl-PL',{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(deadline);return{deadline,date,remaining}}
function decorateOfferDeadlines(){document.querySelectorAll('.job-card').forEach(card=>{if(card.querySelector('.offer-deadline'))return;const j=jobs.find(x=>x.id===+card.dataset.id),meta=card.querySelector('.job-meta');if(!j||!meta)return;const d=offerDeadlineLabel(j);meta.insertAdjacentHTML('afterbegin',`<span class="offer-deadline">◷ Zgłoszenia: ${d.date}<small data-offer-deadline="${d.deadline.getTime()}">pozostało ${d.remaining}</small></span>`)})}
