function editAdminJob(id){const j=jobs.find(x=>x.id===id);if(!canManageJob(j)||!j)return;editingJobId=id;const form=document.querySelector('#adminJobForm'),d=getJobDetails(j),clock=n=>`${String(Math.floor(n)).padStart(2,'0')}:${String(Math.round(n%1*60)).padStart(2,'0')}`;form.elements.role.value=j.role;form.elements.company.value=j.company;form.elements.area.value=j.area;form.elements.address.value=d.address;form.elements.contactName.value=d.contactName;form.elements.contactPhone.value=d.contactPhone;form.elements.day.value=j.day;form.elements.industry.value=j.industry;form.elements.start.value=clock(j.start);form.elements.end.value=clock(j.end);form.elements.rate.value=j.rate;form.elements.tasks.value=(j.tasks||[]).join(', ');form.elements.arrival.value=d.arrival;form.elements.dressCode.value=d.dressCode;form.elements.documents.value=d.documents;form.elements.instructions.value=d.instructions;document.querySelector('#jobFormEyebrow').textContent='EDYCJA OFERTY';document.querySelector('#jobFormTitle').textContent=j.role;document.querySelector('#jobFormSubmit').textContent='Zapisz zmiany';document.querySelector('#jobFormModal').showModal()}
function addAdminJob(form){if(!canManageJobs())return;const d=new FormData(form),days={monday:'Poniedziałek',tuesday:'Wtorek',wednesday:'Środa'},icons={office:'▤',events:'✦',retail:'◼',logistics:'⌂',field:'◎'},start=d.get('start'),end=d.get('end'),industry=d.get('industry');if(end<=start)return toast('Godzina zakończenia musi być późniejsza niż rozpoczęcia.');const values={role:d.get('role').trim(),company:d.get('company').trim(),icon:icons[industry],date:days[d.get('day')],day:d.get('day'),time:`${start}–${end}`,start:+start.split(':')[0]+(+start.split(':')[1]/60),end:+end.split(':')[0]+(+end.split(':')[1]/60),rate:+d.get('rate'),area:d.get('area').trim(),industry,tasks:d.get('tasks').split(',').map(x=>x.trim()).filter(Boolean),address:d.get('address').trim(),contactName:d.get('contactName').trim(),contactPhone:d.get('contactPhone').trim(),arrival:d.get('arrival').trim(),dressCode:d.get('dressCode').trim(),documents:d.get('documents').trim(),instructions:d.get('instructions').trim()};if(editingJobId){const edited=jobs.find(x=>x.id===editingJobId);if(!canManageJob(edited))return;Object.assign(edited,values)}else{jobs.unshift({id:Date.now(),...values,ownerEmail:authUser.email,applicants:0,lat:52.2297,lng:21.0122,match:90,color:'#dbeee6',newness:Date.now(),experience:false,english:false,active:true})}saveJobs();document.querySelector('#jobFormModal').close();form.reset();toast(editingJobId?'Zmiany w ofercie zostały zapisane.':'Nowa oferta została opublikowana.');editingJobId=null}
function switchAuthTab(tab){document.querySelectorAll('[data-auth-tab]').forEach(b=>b.classList.toggle('active',b.dataset.authTab===tab));document.querySelector('#loginForm').classList.toggle('hidden',tab!=='login');document.querySelector('#registerForm').classList.toggle('hidden',tab!=='register');document.querySelector('#loginError').textContent='';document.querySelector('#registerError').textContent=''}
let selectedLoginRole='user',selectedRegisterRole='user';
function setLoginRole(role){selectedLoginRole=role;document.querySelectorAll('#loginRolePicker [data-role]').forEach(button=>button.classList.toggle('active',button.dataset.role===role));document.querySelector('#loginError').textContent=''}
function setRegisterRole(role){selectedRegisterRole=role;document.querySelectorAll('#registerRolePicker [data-role]').forEach(button=>button.classList.toggle('active',button.dataset.role===role));document.querySelectorAll('#registerForm [data-worker-field]').forEach(field=>{field.hidden=role!=='user';field.querySelectorAll('input').forEach(input=>input.required=role==='user')});document.querySelectorAll('#registerForm [data-employer-field]').forEach(field=>{field.hidden=role!=='employer';field.querySelectorAll('input').forEach(input=>input.required=role==='employer')});document.querySelector('#registerError').textContent=''}
function setupAuthRoleSelection(){const loginForm=document.querySelector('#loginForm'),registerForm=document.querySelector('#registerForm'),loginPicker=document.createElement('section'),registerPicker=document.createElement('section');loginPicker.id='loginRolePicker';loginPicker.className='auth-role-picker';loginPicker.innerHTML='<small>TYP KONTA</small><div class="auth-role-options"><button type="button" class="active" data-role="user"><b>👤</b><span>Pracownik</span></button><button type="button" data-role="employer"><b>▣</b><span>Pracodawca</span></button><button type="button" data-role="admin"><b>⚙</b><span>Administrator</span></button></div>';registerPicker.id='registerRolePicker';registerPicker.className='auth-role-picker register-role-picker';registerPicker.innerHTML='<small>KIM JESTEŚ?</small><div class="auth-role-options two"><button type="button" class="active" data-role="user"><b>👤</b><span>Chcę pracować<em>Konto pracownika</em></span></button><button type="button" data-role="employer"><b>▣</b><span>Reprezentuję firmę<em>Konto pracodawcy</em></span></button></div>';loginForm.prepend(loginPicker);registerForm.prepend(registerPicker);const nameRow=registerPicker.nextElementSibling;nameRow.dataset.workerField='';const contactHeading=document.createElement('p');contactHeading.className='auth-section-label';contactHeading.dataset.employerField='';contactHeading.textContent='DANE OSOBY KONTAKTOWEJ';nameRow.before(contactHeading);const companyFields=document.createElement('div');companyFields.className='employer-registration';companyFields.dataset.employerField='';companyFields.innerHTML='<label>Nazwa firmy<input name="companyName" autocomplete="organization"></label><label>NIP<input name="nip" inputmode="numeric" pattern="[0-9]{10}" maxlength="10" placeholder="10 cyfr"></label><p>Utworzysz konto firmy. Po zalogowaniu zobaczysz wyłącznie własne oferty, kandydatów, statusy oraz rozliczenia.</p>';contactHeading.before(companyFields);[registerForm.elements.birthDate.closest('label'),registerForm.elements.adultDeclaration.closest('label'),registerForm.elements.workRightDeclaration.closest('label')].forEach(field=>field.dataset.workerField='');const employerDeclaration=document.createElement('label');employerDeclaration.className='terms-check';employerDeclaration.dataset.employerField='';employerDeclaration.innerHTML='<input name="employerDeclaration" type="checkbox"><span>Oświadczam, że jestem uprawniony/a do reprezentowania firmy i podaję prawdziwe dane.</span>';registerForm.elements.workRightDeclaration.closest('label').after(employerDeclaration);loginPicker.querySelectorAll('[data-role]').forEach(button=>button.onclick=()=>setLoginRole(button.dataset.role));registerPicker.querySelectorAll('[data-role]').forEach(button=>button.onclick=()=>setRegisterRole(button.dataset.role));setRegisterRole('user')}
function openAuth(tab='login',action=null){pendingAuthAction=action;if(jobModal.open)jobModal.close();switchAuthTab(tab);document.querySelector('#authModal').showModal();setTimeout(()=>document.querySelector(`#${tab}Form input`).focus(),100)}
function requireAuth(action){if(authUser)return action();openAuth('login',action)}
function finishAuth(user){authUser={firstName:user.firstName,lastName:user.lastName,email:user.email,role:user.role||'user',companyName:user.companyName||'',nip:user.nip||''};localStorage.setItem('flexo-session',JSON.stringify(authUser));document.querySelector('#authModal').close();renderAuthState();renderJobs();renderBooked();renderAdminJobs();renderWorkerNotifications();toast(`Witaj, ${user.companyName||user.firstName}!`);const action=pendingAuthAction;pendingAuthAction=null;if(authUser.role==='employer')switchView('employer');else if(authUser.role==='admin')switchView('admin');else if(action)setTimeout(action,150);else switchView('discover')}
function login(form){const d=new FormData(form),email=d.get('email').trim().toLowerCase(),user=registeredUsers.find(x=>x.email.toLowerCase()===email&&x.password===d.get('password')),error=document.querySelector('#loginError');if(!user){error.textContent='Nieprawidłowy e-mail lub hasło.';return}if((user.role||'user')!==selectedLoginRole){const labels={user:'pracownika',employer:'pracodawcy',admin:'administratora'};error.textContent=`To jest konto ${labels[user.role||'user']}. Wybierz właściwy typ konta powyżej.`;return}finishAuth(user);form.reset()}
function ageFromBirthDate(value){const birth=new Date(`${value}T00:00:00`),today=new Date();if(Number.isNaN(birth.getTime())||birth>today)return-1;let age=today.getFullYear()-birth.getFullYear();const month=today.getMonth()-birth.getMonth();if(month<0||(month===0&&today.getDate()<birth.getDate()))age--;return age}
function setupRegistrationVerification(){setupAuthRoleSelection();const input=document.querySelector('#registerForm [name="birthDate"]'),cutoff=new Date();cutoff.setFullYear(cutoff.getFullYear()-18);input.max=cutoff.toISOString().slice(0,10);setupLegalDocuments()}
function setupLegalDocuments(){const termsLabel=document.querySelector('#registerForm [name="terms"]').closest('label').querySelector('span');termsLabel.innerHTML='Akceptuję <button type="button" class="legal-link" data-legal="terms">regulamin</button> i <button type="button" class="legal-link" data-legal="privacy">politykę prywatności</button>.';const modal=document.createElement('dialog');modal.id='legalModal';modal.className='legal-modal';modal.innerHTML='<button class="modal-close" aria-label="Zamknij">×</button><h2 id="legalTitle"></h2><p class="legal-version"></p><div class="legal-content"></div><button type="button" class="primary legal-accept">Przeczytałem/am — zamknij</button>';document.body.appendChild(modal);const documents={pl:{terms:{title:'Regulamin platformy Flexo',body:'<h3>1. Zakres usługi</h3><p>Flexo umożliwia przeglądanie ofert pracy dorywczej, zgłaszanie kandydatur oraz kojarzenie pracowników z pracodawcami. Zgłoszenie i potwierdzenie kandydata oznaczają wyłącznie dopasowanie stron. Nie zawierają umowy o pracę, zlecenia ani innej umowy dotyczącej wykonywania pracy.</p><h3>2. Konto użytkownika</h3><p>Użytkownik podaje prawdziwe i aktualne dane, chroni dostęp do konta oraz nie udostępnia go innym osobom. Konto pracownika jest przeznaczone dla osób pełnoletnich, które mają prawo do legalnej pracy w Polsce.</p><h3>3. Zgłoszenia i zmiany</h3><p>Pracodawca wybiera jednego z kandydatów. Po potwierdzeniu obie strony otrzymują status dopasowania. W przypadku zwykłych zleceń rezygnacja pracownika lub pracodawcy jest możliwa najpóźniej 8 godzin przed rozpoczęciem zmiany. Zlecenie ad hoc, którego start przypada w ciągu 8 godzin od zgłoszenia, po zaakceptowaniu kandydata nie może zostać odwołane przez żadną ze stron. Nie ogranicza to prawa pracownika do odmowy pracy w razie niezgodnych, niebezpiecznych lub nielegalnych warunków.</p><h3>4. Obowiązki stron</h3><p>Pracownik wykonuje uzgodnione zadania zgodnie z opisem oferty i zasadami bezpieczeństwa. Pracodawca zapewnia prawdziwy opis pracy, bezpieczne warunki oraz uzgodnione rozliczenie.</p><h3>5. Odpowiedzialność i blokada konta</h3><p>Nadużycia, fałszywe dane, dyskryminacja lub powtarzające się nieusprawiedliwione nieobecności mogą prowadzić do ograniczenia konta.</p><h3>6. Kontakt i reklamacje</h3><p>Pytania i reklamacje: support@flexo.example.</p><h3>7. Rola Flexo i zawarcie umowy</h3><p>Flexo jest portalem umożliwiającym znalezienie się stron. Nie jest pracodawcą, agencją pracy tymczasowej ani stroną umowy dotyczącej wykonywania pracy. Właściwą umowę pracownik i pracodawca zawierają bezpośrednio, poza platformą i przed rozpoczęciem pracy.</p><h3>8. Zgodność warunków</h3><p>Pracodawca odpowiada za zgodność rodzaju umowy, wynagrodzenia, godzin, obowiązków i pozostałych warunków z opublikowaną ofertą. Pracownik nie ma obowiązku podpisywania umowy ani rozpoczynania pracy na warunkach innych niż przedstawione w ofercie.</p><h3>9. Problem stwierdzony na miejscu</h3><p>Jeżeli pracownik dotrze pod wskazany adres, a pracodawca odmówi zawarcia umowy, zaproponuje inne wynagrodzenie, obowiązki, godziny lub rodzaj umowy albo przedstawi warunki niebezpieczne lub niezgodne z prawem, pracownik może odmówić rozpoczęcia pracy i zgłosić problem w aplikacji. Takie zdarzenie nie jest traktowane jako nieusprawiedliwiona rezygnacja pracownika.</p><h3>10. Prowizja i wyjaśnienie zgłoszenia</h3><p>Zgłoszenie problemu nie powoduje automatycznego anulowania prowizji należnej od pracodawcy za skuteczne dopasowanie i pojawienie się pracownika. Flexo może zażądać wyjaśnień i dowodów od obu stron. Ostateczne rozliczenie następuje po analizie zgłoszenia zgodnie z cennikiem i umową z pracodawcą.</p><h3>11. Wersja demonstracyjna</h3><p>Dokument jest projektem funkcjonalnym. Przed uruchomieniem komercyjnym wymaga uzupełnienia danych operatora, cennika, procedury reklamacyjnej oraz weryfikacji przez prawnika.</p>'},privacy:{title:'Polityka prywatności',body:'<h3>1. Administrator danych</h3><p>Administratorem danych będzie operator Flexo. Przed uruchomieniem komercyjnym należy uzupełnić jego pełną nazwę, adres oraz dane kontaktowe.</p><h3>2. Jakie dane przetwarzamy</h3><p>Możemy przetwarzać dane konta i profilu, datę urodzenia, deklaracje pełnoletności i prawa do pracy, dane kontaktowe, historię zgłoszeń, zmian, ocen i rezygnacji oraz dane techniczne. Nie zbieramy numeru PESEL przy rejestracji.</p><h3>3. Cele przetwarzania</h3><p>Dane służą utworzeniu konta, dopasowaniu ofert, obsłudze zgłoszeń i zmian, bezpieczeństwu, reklamacjom oraz obowiązkom prawnym.</p><h3>4. Odbiorcy i okres przechowywania</h3><p>Dane mogą otrzymywać właściwy pracodawca i dostawcy usług. Przechowujemy je przez czas działania konta, a później tylko przez okres wymagany dla roszczeń lub obowiązków prawnych.</p><h3>5. Prawa użytkownika</h3><p>Użytkownik może żądać dostępu, poprawienia, usunięcia lub ograniczenia danych, a w odpowiednich przypadkach także przeniesienia lub wnieść sprzeciw. Może złożyć skargę do Prezesa UODO.</p><h3>6. Kontakt</h3><p>Sprawy prywatności: privacy@flexo.example. To wersja demonstracyjna wymagająca uzupełnienia przed rozpoczęciem rzeczywistego przetwarzania danych.</p>'}},en:{terms:{title:'Flexo Platform Terms',body:'<h3>1. Service</h3><p>Flexo lets users browse temporary jobs, apply for shifts and connect with employers. An application and employer confirmation only match the parties. They do not create an employment, service or other work contract.</p><h3>2. Account</h3><p>Users provide accurate data and protect their account. Worker accounts are for adults legally entitled to work in Poland.</p><h3>3. Shifts</h3><p>The employer selects a candidate. For standard jobs, either party may cancel no later than 8 hours before the shift. An ad hoc job starting within 8 hours cannot be cancelled by either party after the candidate is accepted. This does not limit the worker’s right to refuse different, unsafe or unlawful conditions.</p><h3>4. Responsibilities</h3><p>Workers perform agreed tasks safely. Employers provide accurate details, safe conditions and the agreed settlement.</p><h3>5. Misuse</h3><p>Fraud, false data, discrimination or repeated unjustified absences may restrict an account.</p><h3>6. Contact</h3><p>Contact support@flexo.example.</p><h3>7. Flexo’s role and the work contract</h3><p>Flexo is a portal that enables the parties to find each other. It is not the employer, a temporary employment agency or a party to the work contract. The worker and employer sign the relevant contract directly, outside the platform and before work begins.</p><h3>8. Consistency of terms</h3><p>The employer is responsible for ensuring that the contract type, pay, hours, duties and other terms match the published offer. A worker is not required to sign or begin work under different terms.</p><h3>9. Problem at the workplace</h3><p>If the worker arrives and the employer refuses to sign a contract, changes the pay, duties, hours or contract type, or presents unsafe or unlawful conditions, the worker may refuse to start and report the problem in the app without a worker cancellation penalty.</p><h3>10. Commission and review</h3><p>A report does not automatically cancel the employer’s Flexo commission for a successful match and the worker’s arrival. Flexo may request evidence from both parties and settle the case under the employer agreement and price list.</p><h3>11. Demonstration version</h3><p>This functional draft requires operator details, pricing, a complaints procedure and legal review before commercial launch.</p>'},privacy:{title:'Privacy Policy',body:'<h3>1. Controller</h3><p>The Flexo operator will be the data controller. Its full details must be added before launch.</p><h3>2. Data</h3><p>We may process profile data, date of birth, eligibility declarations, contact details, applications, shifts, ratings and security data. We do not collect PESEL during registration.</p><h3>3. Purposes</h3><p>Data supports accounts, matching, shifts, security, complaints and legal duties.</p><h3>4. Recipients and retention</h3><p>Relevant employers and service providers may receive data. Retention lasts while needed for the account, claims or legal duties.</p><h3>5. Rights</h3><p>Users may request access, correction, deletion or restriction and exercise other applicable data rights.</p><h3>6. Contact</h3><p>Contact privacy@flexo.example. This demo document must be completed before real processing begins.</p>'}}};function open(type){const doc=documents[currentLanguage]?.[type]||documents.pl[type];modal.querySelector('#legalTitle').textContent=doc.title;modal.querySelector('.legal-version').textContent=currentLanguage==='en'?'Version: 21 August 2026':'Wersja: 21 sierpnia 2026';modal.querySelector('.legal-content').innerHTML=doc.body;modal.querySelector('.legal-accept').textContent=currentLanguage==='en'?'I have read it — close':'Przeczytałem/am — zamknij';modal.showModal()}const legalNav=document.createElement('div');legalNav.className='legal-access';legalNav.innerHTML='<button type="button" data-public-legal="terms">Regulamin</button><span>·</span><button type="button" data-public-legal="privacy">Prywatność</button>';document.body.appendChild(legalNav);legalNav.querySelectorAll('[data-public-legal]').forEach(button=>button.onclick=()=>open(button.dataset.publicLegal));document.querySelectorAll('[data-legal]').forEach(button=>button.onclick=e=>{e.preventDefault();e.stopPropagation();open(button.dataset.legal)});modal.querySelectorAll('.modal-close,.legal-accept').forEach(button=>button.onclick=()=>modal.close())}
function register(form){const d=new FormData(form),email=d.get('email').trim().toLowerCase(),birthDate=d.get('birthDate'),error=document.querySelector('#registerError'),isEmployer=selectedRegisterRole==='employer';if(!isEmployer&&ageFromBirthDate(birthDate)<18){error.textContent='Rejestracja jest dostępna wyłącznie dla osób, które ukończyły 18 lat.';return}if(!isEmployer&&(!d.get('adultDeclaration')||!d.get('workRightDeclaration'))){error.textContent='Zaznacz wymagane oświadczenia.';return}if(isEmployer&&(!d.get('companyName')?.trim()||!/^[0-9]{10}$/.test(d.get('nip')||'')||!d.get('employerDeclaration'))){error.textContent='Podaj nazwę firmy, 10-cyfrowy NIP i potwierdź prawo do reprezentowania firmy.';return}if(registeredUsers.some(x=>x.email.toLowerCase()===email)){error.textContent='Konto z tym adresem już istnieje.';return}const user={firstName:d.get('firstName').trim(),lastName:d.get('lastName').trim(),birthDate:isEmployer?'':birthDate,email,password:d.get('password'),role:isEmployer?'employer':'user',companyName:isEmployer?d.get('companyName').trim():'',nip:isEmployer?d.get('nip'):'',adultDeclared:!isEmployer,workRightDeclared:!isEmployer,employerDeclared:isEmployer,verificationStatus:'declared'};registeredUsers.push(user);localStorage.setItem('flexo-users',JSON.stringify(registeredUsers));if(!isEmployer){userProfile={...userProfile,firstName:user.firstName,lastName:user.lastName,email:user.email,birthDate:user.birthDate,adultDeclared:true,workRightDeclared:true};localStorage.setItem('flexo-profile',JSON.stringify(userProfile));renderProfile()}finishAuth(user);form.reset();setRegisterRole('user')}
function renderAuthState(){const sidebar=document.querySelector('.sidebar-user'),mobile=document.querySelector('#mobileAccountAction'),isAdmin=authUser?.role==='admin',isEmployer=authUser?.role==='employer',workerViews=['discover','schedule','wallet','profile'];document.querySelectorAll('[data-view="admin"]').forEach(x=>x.hidden=!isAdmin);document.querySelectorAll('[data-view="employer"]').forEach(x=>x.hidden=!isEmployer);document.querySelectorAll('[data-view]').forEach(x=>{if(workerViews.includes(x.dataset.view))x.hidden=isAdmin||isEmployer});if(!isAdmin&&document.querySelector('#admin').classList.contains('active-view'))switchView(isEmployer?'employer':'discover');if(!isEmployer&&document.querySelector('#employer').classList.contains('active-view'))switchView(isAdmin?'admin':'discover');if(authUser){const roleLabel=isAdmin?'Administrator':isEmployer?'Pracodawca':userProfile.city,avatar=isAdmin?'AF':isEmployer?'EC':initials();sidebar.classList.remove('guest');sidebar.querySelector('strong').textContent=authUser.firstName;sidebar.querySelector('small').textContent=roleLabel;sidebar.querySelector('.avatar').textContent=avatar;document.querySelector('#accountAction').textContent='Wyjdź';document.querySelector('#accountAction').title='Wyloguj się';mobile.classList.remove('guest');mobile.textContent=avatar}else{sidebar.classList.add('guest');sidebar.querySelector('strong').textContent='Gość';sidebar.querySelector('small').textContent='Przeglądasz bez konta';sidebar.querySelector('.avatar').textContent='?';document.querySelector('#accountAction').textContent='Zaloguj';document.querySelector('#accountAction').title='Zaloguj się';mobile.classList.add('guest');mobile.textContent='?'}}
function accountAction(){if(!authUser)return openAuth();if(confirm('Czy chcesz się wylogować?')){authUser=null;localStorage.removeItem('flexo-session');renderAuthState();renderAdminJobs();switchView('discover');toast('Wylogowano. Nadal możesz przeglądać oferty.')}}
function goHome(){switchView(authUser?.role==='admin'?'admin':authUser?.role==='employer'?'employer':'discover')}
function openMapJob(id){document.querySelector('#mapModal').close();setTimeout(()=>openJob(id),100)}
function setupDemoAccounts(){const box=document.createElement('div');box.className='demo-accounts';box.innerHTML='<small>KONTA TESTOWE</small><div><button data-role="user" data-demo="lukasz@example.pl|flexo123">Pracownik</button><button data-role="employer" data-demo="firma@flexo.pl|firma123">Pracodawca</button><button data-role="admin" data-demo="admin@flexo.pl|admin123">Administrator</button></div>';document.querySelector('#authModal').insertBefore(box,document.querySelector('.auth-security'));box.querySelectorAll('[data-demo]').forEach(button=>button.onclick=()=>{const [email,password]=button.dataset.demo.split('|'),form=document.querySelector('#loginForm');switchAuthTab('login');setLoginRole(button.dataset.role);form.elements.email.value=email;form.elements.password.value=password;form.elements.email.focus()})}
function setupAdminDetails(){const modal=document.createElement('dialog');modal.id='adminDetailsModal';modal.className='admin-details-modal';modal.innerHTML='<button class="modal-close" aria-label="Zamknij">×</button><div id="adminDetailsContent"></div>';document.body.appendChild(modal);modal.querySelector('.modal-close').onclick=()=>modal.close()}
function initMap(){if(typeof L==='undefined'){toast('Mapa nie mogła zostać załadowana. Sprawdź połączenie z internetem.');return}if(!jobsMap){jobsMap=L.map('jobsMap',{zoomControl:true}).setView([userLocation.lat,userLocation.lng],13);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(jobsMap);jobMapLayer=L.layerGroup().addTo(jobsMap);startMarker=L.marker([userLocation.lat,userLocation.lng],{draggable:true,title:'Punkt startowy'}).addTo(jobsMap).bindTooltip('Twój punkt startowy');radiusCircle=L.circle([userLocation.lat,userLocation.lng],{radius:filters.radius*1000,color:'#0d5b48',fillColor:'#bdf5da',fillOpacity:.16,weight:2}).addTo(jobsMap);startMarker.on('dragend',e=>setMapOrigin(e.target.getLatLng()));jobsMap.on('click',e=>setMapOrigin(e.latlng))}setTimeout(()=>{jobsMap.invalidateSize();updateMap()},50)}
function setMapOrigin(pos){userLocation={lat:pos.lat,lng:pos.lng,label:'Wybrany punkt na mapie'};locationFilterEnabled=true;updateMap()}
function clearRoute(){routeRequestId++;if(routeLine&&jobsMap)jobsMap.removeLayer(routeLine);routeLine=null;selectedMapJobId=null;document.querySelector('#routeSummary').hidden=true}
async function drawRouteToJob(id,fit=true){if(!locationFilterEnabled)return toast('Najpierw ustaw punkt startowy lub użyj swojej lokalizacji.');const job=jobs.find(j=>j.id===id);if(!job)return;selectedMapJobId=id;const requestId=++routeRequestId,profiles={walk:'foot',bike:'bike',transit:'car',car:'car'},profile=profiles[travelMode],url=`https://routing.openstreetmap.de/routed-${profile}/route/v1/driving/${userLocation.lng},${userLocation.lat};${job.lng},${job.lat}?overview=full&geometries=geojson`;const modeIcons={walk:'🚶',bike:'🚲',transit:'🚌',car:'🚗'},summary=document.querySelector('#routeSummary');document.querySelector('#routeIcon').textContent=modeIcons[travelMode];document.querySelector('#routeJobName').textContent=job.role;document.querySelector('#routeMeta').textContent='Wyznaczam trasę po drogach…';summary.hidden=false;try{const response=await fetch(url);if(!response.ok)throw new Error('routing');const data=await response.json();if(requestId!==routeRequestId||!data.routes?.length)return;const route=data.routes[0],points=route.geometry.coordinates.map(([lng,lat])=>[lat,lng]);if(routeLine)jobsMap.removeLayer(routeLine);routeLine=L.polyline(points,{color:'#0d5b48',weight:5,opacity:.9}).addTo(jobsMap);let minutes=Math.max(1,Math.round(route.duration/60));if(travelMode==='transit')minutes=Math.round(minutes*1.25+8);const label=travelMode==='transit'?'komunikacją (orientacyjnie)':estimateTravel(job).label;document.querySelector('#routeMeta').textContent=`${(route.distance/1000).toFixed(1).replace('.',',')} km · około ${minutes} min ${label}`;if(fit)jobsMap.fitBounds(routeLine.getBounds().pad(.15),{maxZoom:15})}catch(error){if(requestId!==routeRequestId)return;document.querySelector('#routeMeta').textContent='Nie udało się teraz wyznaczyć trasy. Spróbuj ponownie.';toast('Serwis trasowania jest chwilowo niedostępny.')}}
function clearLocationFilter(){locationFilterEnabled=false;clearRoute();renderJobs();updateMap();toast('Filtrowanie według lokalizacji zostało wyłączone.')}
function updateMap(){if(!jobsMap)return;startMarker.setLatLng([userLocation.lat,userLocation.lng]).setOpacity(locationFilterEnabled?1:.45);radiusCircle.setLatLng([userLocation.lat,userLocation.lng]).setRadius(filters.radius*1000).setStyle({opacity:locationFilterEnabled?1:0,fillOpacity:locationFilterEnabled?0.16:0});jobMapLayer.clearLayers();let count=0;jobs.filter(j=>j.active!==false&&!jobIsTaken(j)).forEach(j=>{const within=!locationFilterEnabled||jobDistance(j)<=filters.radius,trip=estimateTravel(j);if(within)count++;const popup=`<div class="map-job-popup"><strong>${j.role}</strong><small>${j.company} · ${j.area}</small><small>${j.date}, ${j.time} · ${j.rate} zł/h</small>${locationFilterEnabled?`<small>${jobDistance(j).toFixed(1).replace('.',',')} km · około ${trip.minutes} min ${trip.label}</small>`:''}<button onclick="openMapJob(${j.id})">Zobacz zlecenie →</button></div>`,marker=L.circleMarker([j.lat,j.lng],{radius:within?9:6,color:within?'#0d5b48':'#8f9c97',fillColor:within?'#d8ff70':'#d9dfdc',fillOpacity:1,weight:2,opacity:within?1:.55,bubblingMouseEvents:false}).addTo(jobMapLayer).bindPopup(popup,{minWidth:190});marker.on('click',()=>drawRouteToJob(j.id,true))});document.querySelector('#mapJobsCount').textContent=count;document.querySelector('#mapLocationLabel').textContent=locationFilterEnabled?userLocation.label:'Nie wybrano';document.querySelector('#mapRadiusOutput').value=filters.radius;document.querySelector('#mapRadius').value=filters.radius;document.querySelector('#mapClearLocation').hidden=!locationFilterEnabled;document.querySelector('#clearLocation').hidden=!locationFilterEnabled;if(selectedMapJobId&&locationFilterEnabled)drawRouteToJob(selectedMapJobId,false)}
function openMap(){document.querySelector('#mapModal').showModal();document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===travelMode));initMap()}
function fitAllMapJobs(){if(!jobsMap)return;const points=jobs.filter(j=>j.active!==false&&!jobIsTaken(j)).map(j=>[j.lat,j.lng]);if(locationFilterEnabled)points.push([userLocation.lat,userLocation.lng]);if(points.length)jobsMap.fitBounds(L.latLngBounds(points).pad(.18),{maxZoom:13});toast('Mapa pokazuje wszystkie dostępne oferty.')}
function saveApplications(){localStorage.setItem('flexo-applications',JSON.stringify(applications));jobs.forEach(j=>j.applicants=applications.filter(a=>a.jobId===j.id).length)}
function expireApplications(){let changed=false;applications.forEach(a=>{if(a.status==='pending'&&Date.now()>a.deadline){a.status='expired';changed=true}});if(changed)saveApplications();return changed}
function myApplication(jobId){return applications.find(a=>a.jobId===jobId&&a.workerEmail===authUser?.email)}
function confirmedJobIdsFor(email){return applications.filter(a=>a.workerEmail===email&&['confirmed','completed'].includes(a.status)).map(a=>a.jobId)}
function applicationStatusText(status){return{pending:'Oczekuje na potwierdzenie pracodawcy',confirmed:'Zlecenie potwierdzone',completed:'Zmiana wykonana i oceniona',rejected:'Pracodawca wybrał inną osobę',expired:'Czas na decyzję pracodawcy minął',worker_cancelled:'Pracownik zrezygnował ze zmiany',employer_cancelled:'Pracodawca anulował zmianę',employer_issue:'Zgłoszono niezgodne warunki na miejscu'}[status]||''}
function submitApplication(id){if(!authUser)return openAuth('login',()=>submitApplication(id));if(authUser.role!=='user')return toast('Na zlecenia mogą zgłaszać się tylko pracownicy.');expireApplications();const job=jobs.find(j=>j.id===id),policy=cancellationPolicyFor(job);if(policy.adHoc&&!confirm(currentLanguage==='en'?'This shift starts in less than 8 hours. Once the employer accepts you, neither party can cancel it. Do you want to apply?':'To zlecenie rozpoczyna się za mniej niż 8 godzin. Po akceptacji pracodawcy żadna ze stron nie będzie mogła go odwołać. Czy na pewno chcesz się zgłosić?'))return;const app=myApplication(id);if(app)return toast(applicationStatusText(app.status));const workerName=`${authUser.firstName} ${authUser.lastName}`;applications.push({id:`${id}-${authUser.email}-${Date.now()}`,jobId:id,workerEmail:authUser.email,workerName,status:'pending',appliedAt:Date.now(),deadline:Date.now()+APPLICATION_DECISION_MS,cancellationPolicy:policy.adHoc?'ad_hoc_locked':'standard_8h'});saveApplications();renderJobs();renderWorkerNotifications();openJob(id);toast('Zgłoszenie wysłane. Pracodawca ma 5 minut na decyzję.')}
function remainingTime(deadline){const seconds=Math.max(0,Math.ceil((deadline-Date.now())/1000));return`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`}
function renderWorkerNotifications(){expireApplications();const box=document.querySelector('#workerNotifications');if(!box)return;if(authUser?.role!=='user'){box.hidden=true;return}const mine=applications.filter(a=>a.workerEmail===authUser.email).sort((a,b)=>b.appliedAt-a.appliedAt);box.hidden=!mine.length;box.innerHTML=mine.map(a=>{const j=jobs.find(x=>x.id===a.jobId);if(!j)return'';const texts={pending:['Oczekuje na potwierdzenie',`Pracodawca wybiera kandydata · pozostało <b data-deadline="${a.deadline}">${remainingTime(a.deadline)}</b>`],confirmed:['Zlecenie potwierdzone ✓','Pracodawca wybrał Ciebie. Zmiana jest w Twoim kalendarzu.'],rejected:['Wybrano inną osobę','Tym razem pracodawca wybrał innego kandydata. Może następnym razem!'],expired:['Brak decyzji w wymaganym czasie','Zgłoszenie wygasło — możesz wybrać inną zmianę.']}[a.status];return`<article class="application-notice ${a.status}"><span>${a.status==='confirmed'?'✓':a.status==='pending'?'◷':'i'}</span><div><small>${j.role} · ${j.company}</small><strong>${texts[0]}</strong><p>${texts[1]}</p></div>${a.status==='confirmed'?`<button onclick="openJob(${j.id})">Szczegóły</button>`:''}</article>`}).join('')}
function candidateProfile(email,name){const known={'lukasz@example.pl':{attendance:98,cancellations:1,city:'Warszawa',skills:['Logistyka','Obsługa wydarzeń','Punktualność']},'maria@example.pl':{attendance:96,cancellations:2,city:'Warszawa',skills:['Obsługa klienta','Rejestracja gości','Eventy']},'jan@example.pl':{attendance:94,cancellations:1,city:'Warszawa',skills:['Logistyka','Pakowanie','Praca zespołowa']}},base=known[email]||{attendance:97,cancellations:0,city:userProfile.city||'Warszawa',skills:userProfile.skills?.length?userProfile.skills:['Dyspozycyjność','Punktualność']},workerReviews=reviews.filter(r=>r.workerEmail===email),rating=workerReviews.length?Math.round(workerReviews.reduce((sum,r)=>sum+r.score,0)/workerReviews.length*10)/10:null;return{...base,rating,completed:workerReviews.length,reviews:workerReviews}}
function openCandidateProfile(email,jobId){const job=jobs.find(j=>j.id===jobId);if(!canManageJob(job))return;const app=applications.find(a=>a.jobId===jobId&&a.workerEmail===email);if(!app)return;const p=candidateProfile(email,app.workerName),modal=document.querySelector('#candidateProfileModal'),initials=app.workerName.split(' ').map(x=>x[0]).join('').slice(0,2);document.querySelector('#candidateProfileContent').innerHTML=`<div class="candidate-profile-head"><div class="avatar large">${initials}</div><div><p class="eyebrow">ZWERYFIKOWANY PRACOWNIK</p><h2>${app.workerName}</h2><p>${p.city} · <strong>${p.rating} ★</strong></p></div></div><div class="candidate-profile-stats"><div><small>OCENA</small><strong>${p.rating} / 5</strong></div><div><small>UKOŃCZONE ZMIANY</small><strong>${p.completed}</strong></div><div><small>FREKWENCJA</small><strong>${p.attendance}%</strong></div><div><small>ANULOWANIA</small><strong>${p.cancellations}</strong></div></div><div class="candidate-profile-section"><small>UMIEJĘTNOŚCI</small><div class="skill-tags">${p.skills.map(s=>`<span>${s}</span>`).join('')}</div></div><div class="candidate-fit"><strong>Dlaczego pasuje do tej zmiany?</strong><p>Potwierdził dostępność w godzinach ${job.time}, ma zweryfikowaną tożsamość i ${p.attendance}% frekwencji.</p></div>${app.status==='pending'?`<button class="candidate-confirm-main" onclick="document.querySelector('#candidateProfileModal').close();confirmCandidate('${app.id}')">Wybierz tego pracownika</button>`:`<div class="management-preview-note">${applicationStatusText(app.status)}</div>`}`;modal.showModal()}
function openCandidates(jobId){const job=jobs.find(j=>j.id===jobId);if(!canManageJob(job))return;expireApplications();const list=applications.filter(a=>a.jobId===jobId).sort((a,b)=>a.appliedAt-b.appliedAt),modal=document.querySelector('#candidatesModal');document.querySelector('#candidatesContent').innerHTML=`<div class="candidate-head"><p class="eyebrow">WYBÓR PRACOWNIKA</p><h2>${job.role}</h2><p>${job.company} · ${job.date}, ${job.time}</p></div><div class="candidate-list">${list.length?list.map(a=>`<div class="candidate-row ${a.status}"><div class="avatar">${a.workerName.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div><strong>${a.workerName}</strong><small>${a.workerEmail}</small><span>${applicationStatusText(a.status)}${a.status==='pending'?` · <b data-deadline="${a.deadline}">${remainingTime(a.deadline)}</b>`:''}</span></div><div class="candidate-actions"><button class="profile-button" onclick="openCandidateProfile('${a.workerEmail}',${jobId})">Zobacz profil</button>${a.status==='pending'?`<button onclick="confirmCandidate('${a.id}')">Wybierz</button>`:`<em>${a.status==='confirmed'?'Wybrany':'Zakończone'}</em>`}</div></div>`).join(''):'<div class="empty">Nikt jeszcze nie zgłosił się do tej zmiany.</div>'}</div>`;modal.showModal()}
function confirmCandidate(applicationId){const chosen=applications.find(a=>a.id===applicationId);if(!chosen||chosen.status!=='pending')return;expireApplications();if(chosen.status!=='pending')return openCandidates(chosen.jobId);applications.forEach(a=>{if(a.jobId===chosen.jobId&&a.status==='pending')a.status=a.id===chosen.id?'confirmed':'rejected'});saveApplications();document.querySelector('#candidatesModal').close();renderJobs();if(jobsMap)updateMap();renderAdminJobs();renderWorkerNotifications();toast(`Wybrano: ${chosen.workerName}. Oferta została zdjęta z publicznej listy.`)}
function resetCandidateTest(){if(authUser?.role!=='employer')return toast('Test kandydatów uruchamia pracodawca.');const owned=jobs.filter(j=>j.ownerEmail===authUser.email&&j.active!==false),ids=new Set(owned.map(j=>j.id)),pool=[['Maria Nowak','maria@example.pl'],['Jan Wiśniewski','jan@example.pl'],['Kasia Zielińska','kasia@example.pl'],['Piotr Wójcik','piotr@example.pl'],['Anna Mazur','anna@example.pl'],['Tomasz Kurek','tomasz@example.pl']];applications=applications.filter(a=>!ids.has(a.jobId));owned.forEach((job,index)=>{for(let n=0;n<2;n++){const [workerName,workerEmail]=pool[(index*2+n)%pool.length],appliedAt=Date.now()+n*500;applications.push({id:`test-${job.id}-${workerEmail}-${Date.now()}`,jobId:job.id,workerEmail,workerName,status:'pending',appliedAt,deadline:appliedAt+APPLICATION_DECISION_MS})}});saveApplications();renderAdminJobs();toast(`Test uruchomiony: kandydaci czekają przy ${owned.length} ofertach. Masz 5 minut na decyzje.`)}
function setupApplicationWorkflow(){const notifications=document.createElement('div');notifications.id='workerNotifications';notifications.className='worker-notifications';notifications.hidden=true;document.querySelector('#discover .hero').after(notifications);const modal=document.createElement('dialog');modal.id='candidatesModal';modal.className='candidates-modal';modal.innerHTML='<button class="modal-close" aria-label="Zamknij">×</button><div id="candidatesContent"></div>';document.body.appendChild(modal);modal.querySelector('.modal-close').onclick=()=>modal.close();const profileModal=document.createElement('dialog');profileModal.id='candidateProfileModal';profileModal.className='candidate-profile-modal';profileModal.innerHTML='<button class="modal-close" aria-label="Zamknij">×</button><div id="candidateProfileContent"></div>';document.body.appendChild(profileModal);profileModal.querySelector('.modal-close').onclick=()=>profileModal.close();setInterval(()=>{if(expireApplications()){renderWorkerNotifications();renderAdminJobs()}document.querySelectorAll('[data-deadline]').forEach(el=>el.textContent=remainingTime(+el.dataset.deadline));document.querySelectorAll('[data-offer-deadline]').forEach(el=>{const left=Math.max(0,+el.dataset.offerDeadline-Date.now()),minutes=Math.floor(left/60000),days=Math.floor(minutes/1440),hours=Math.floor(minutes%1440/60),mins=minutes%60;el.textContent=`${el.closest('.offer-deadline')?'pozostało ':'Pozostało '}${days?`${days} d ${hours} godz.`:hours?`${hours} godz. ${mins} min`:`${Math.max(0,mins)} min`}`})},1000)}
const openJobApplicationBase=openJob;openJob=function(id){openJobApplicationBase(id);if(!authUser||authUser.role!=='user')return;expireApplications();const app=myApplication(id),button=jobModal.querySelector('.book-button');if(!button)return;const states={pending:'Oczekuje na potwierdzenie…',confirmed:'Zlecenie potwierdzone ✓',rejected:'Nie wybrano do tej zmiany',expired:'Zgłoszenie wygasło'};button.textContent=app?states[app.status]:'Biorę tę zmianę';button.disabled=!!app;button.onclick=()=>submitApplication(id);if(app)button.insertAdjacentHTML('beforebegin',`<div class="application-state ${app.status}"><strong>${applicationStatusText(app.status)}</strong><p>${app.status==='pending'?`Pracodawca ma czas na decyzję: <b data-deadline="${app.deadline}">${remainingTime(app.deadline)}</b>`:app.status==='confirmed'?'Możesz przygotować się do zmiany. Szczegóły są powyżej.':app.status==='rejected'?'Nie blokujemy Ci grafiku — możesz od razu wybrać inną ofertę.':'Nie musisz już czekać na tę ofertę.'}</p></div>`)}
function restrictEmployerContact(jobId){if(authUser?.role!=='user')return;const app=myApplication(jobId),matched=app&&['confirmed','completed'].includes(app.status);if(matched)return;const privateGrid=jobModal.querySelector('.private-details-grid');if(!privateGrid)return;const contactFields=privateGrid.querySelectorAll('.private-detail:not(.wide)');if(contactFields.length<2)return;contactFields[0].innerHTML='<small>OSOBA KONTAKTOWA</small><strong class="locked-contact">🔒 Dostępna po zaakceptowaniu</strong>';contactFields[1].innerHTML='<small>TELEFON SŁUŻBOWY</small><strong class="locked-contact">🔒 Dostępny po zaakceptowaniu</strong>';privateGrid.insertAdjacentHTML('afterend','<div class="contact-access-note"><strong>Dane kontaktowe po potwierdzeniu matchu</strong><p>Imię, nazwisko i numer telefonu koordynatora zostaną odsłonięte, gdy pracodawca wybierze Cię do tej zmiany.</p></div>')}
const openJobContactBase=openJob;openJob=function(id){openJobContactBase(id);decorateJobDeadline(id);restrictEmployerContact(id);const app=myApplication(id);if(authUser?.role==='user'&&app?.status==='completed'){const button=jobModal.querySelector('.book-button'),message=jobModal.querySelector('.application-state p');if(button)button.textContent='Zmiana wykonana i oceniona ✓';if(message)message.textContent='Zmiana została zakończona, a ocena pracodawcy dodana do Twojego profilu.'}}
const renderJobsApplicationBase=renderJobs;renderJobs=function(){expireApplications();renderJobsApplicationBase();decorateOfferDeadlines();document.querySelectorAll('.job-card').forEach(card=>{const app=myApplication(+card.dataset.id),button=card.querySelector('.job-footer button');if(app&&button)button.textContent={pending:'Oczekuje ◷',confirmed:'Potwierdzone ✓',rejected:'Nie wybrano',expired:'Wygasło'}[app.status]});renderWorkerNotifications()}
const renderBookedApplicationBase=renderBooked;renderBooked=function(){if(authUser?.role!=='user')return renderBookedApplicationBase();const ids=confirmedJobIdsFor(authUser.email),list=ids.map(id=>jobs.find(j=>j.id===id)).filter(Boolean);document.querySelector('#shiftCount').textContent=list.length;document.querySelector('#bookedList').innerHTML=list.length?list.map(j=>`<article class="booked-card"><div class="date-tile"><small>${j.date.slice(0,3).toUpperCase()}</small><strong>${j.start}</strong></div><div class="grow"><h3>${j.role}</h3><p>${j.company} · ${j.time} · ${j.area}</p><strong>${j.rate*(j.end-j.start)} zł</strong></div><button class="primary" onclick="openJob(${j.id})">Szczegóły</button></article>`).join(''):'<div class="empty">Nie masz jeszcze potwierdzonych zmian.</div>'}
function saveReviews(){localStorage.setItem('flexo-reviews',JSON.stringify(reviews))}
function openReviewForm(workerEmail,jobId){const job=jobs.find(j=>j.id===jobId),app=applications.find(a=>a.jobId===jobId&&a.workerEmail===workerEmail);if(!canManageJob(job)||!app)return;if(app.status==='completed'||reviews.some(r=>r.workerEmail===workerEmail&&r.jobId===jobId&&r.employerEmail===authUser.email))return toast('Ta zmiana została już oceniona.');if(app.status!=='confirmed')return;const form=document.querySelector('#reviewForm');form.workerEmail.value=workerEmail;form.jobId.value=jobId;form.querySelector('[data-worker]').textContent=app.workerName;form.querySelector('[data-job]').textContent=`${job.role} · ${job.date}, ${job.time}`;['punctuality','quality','cooperation'].forEach(key=>form[key].value=5);form.comment.value='';document.querySelector('#candidateProfileModal')?.close();document.querySelector('#reviewModal').showModal()}
function submitReview(form){const workerEmail=form.workerEmail.value,jobId=+form.jobId.value,app=applications.find(a=>a.jobId===jobId&&a.workerEmail===workerEmail);if(!app||app.status!=='confirmed'||reviews.some(r=>r.workerEmail===workerEmail&&r.jobId===jobId&&r.employerEmail===authUser.email))return toast('Ta zmiana została już oceniona.');const punctuality=+form.punctuality.value,quality=+form.quality.value,cooperation=+form.cooperation.value,score=Math.round((punctuality+quality+cooperation)/3*10)/10,entry={id:`review-${jobId}-${workerEmail}`,workerEmail,jobId,employerEmail:authUser.email,punctuality,quality,cooperation,score,comment:form.comment.value.trim(),createdAt:Date.now()};reviews.push(entry);app.status='completed';saveReviews();saveApplications();document.querySelector('#reviewModal').close();document.querySelector('#candidateProfileModal')?.close();document.querySelector('#candidatesModal')?.close();renderAdminJobs();renderWorkerNotifications();renderDashboardSummary();toast(`Ocena ${score}/5 została zapisana. Zmiana została zakończona.`)}
function setupReviewWorkflow(){const modal=document.createElement('dialog');modal.id='reviewModal';modal.className='review-modal';modal.innerHTML=`<button class="modal-close" aria-label="Zamknij">×</button><form id="reviewForm" class="review-form"><input type="hidden" name="workerEmail"><input type="hidden" name="jobId"><p class="eyebrow">OCENA PO WYKONANEJ ZMIANIE</p><h2 data-worker></h2><p class="review-job" data-job></p><div class="review-grid">${[['punctuality','Punktualność'],['quality','Jakość pracy'],['cooperation','Współpraca']].map(([name,label])=>`<label>${label}<select name="${name}" required><option value="5">5 — świetnie</option><option value="4">4 — dobrze</option><option value="3">3 — poprawnie</option><option value="2">2 — słabo</option><option value="1">1 — bardzo słabo</option></select></label>`).join('')}</div><label class="review-comment">Komentarz (opcjonalnie)<textarea name="comment" rows="3" maxlength="300" placeholder="Co warto wiedzieć o współpracy?"></textarea></label><p class="review-note">Ocena profilu to średnia z trzech kryteriów ze wszystkich ukończonych zmian.</p><button class="candidate-confirm-main" type="submit">Zapisz ocenę i zakończ zmianę</button></form>`;document.body.appendChild(modal);modal.querySelector('.modal-close').onclick=()=>modal.close();modal.querySelector('form').onsubmit=e=>{e.preventDefault();submitReview(e.target)}}
function openCancellation(jobId){const job=jobs.find(j=>j.id===jobId),app=applications.find(a=>a.jobId===jobId&&a.status==='confirmed');if(!job||!app)return toast('Ta zmiana nie może już zostać anulowana.');const byWorker=authUser?.role==='user'&&app.workerEmail===authUser.email,byEmployer=['employer','admin'].includes(authUser?.role)&&canManageJob(job);if(!byWorker&&!byEmployer)return;const form=document.querySelector('#cancellationForm'),shift=nextShiftDate(job),hours=(shift-Date.now())/3600000;if(shift-Date.now()<CANCELLATION_CUTOFF_MS)return toast('Anulowanie online jest możliwe najpóźniej 8 godzin przed zmianą. W nagłej sytuacji skontaktuj się z pomocą Flexo.');form.jobId.value=jobId;form.cancelledBy.value=byWorker?'worker':'employer';form.querySelector('[data-cancel-title]').textContent=byWorker?'Nie możesz przyjść na zmianę?':'Anulować potwierdzoną zmianę?';form.querySelector('[data-cancel-job]').textContent=`${job.role} · ${job.company} · ${job.date}, ${job.time}`;form.querySelector('[data-cancel-warning]').innerHTML=hours<24?'<strong>Do zmiany zostało mniej niż 24 godziny.</strong> Nadal możesz anulować, ale decyzja zostanie oznaczona jako późna i zapisana w historii.':'Druga strona otrzyma informację, a decyzja zostanie zapisana w historii zlecenia.';form.reason.value='';form.details.value='';document.querySelector('#cancellationModal').showModal()}
function submitCancellation(form){const jobId=+form.jobId.value,job=jobs.find(j=>j.id===jobId),app=applications.find(a=>a.jobId===jobId&&a.status==='confirmed'),cancelledBy=form.cancelledBy.value;if(!job||!app)return toast('Ta zmiana została już zamknięta lub anulowana.');const byWorker=cancelledBy==='worker'&&authUser?.role==='user'&&app.workerEmail===authUser.email,byEmployer=cancelledBy==='employer'&&['employer','admin'].includes(authUser?.role)&&canManageJob(job);if(!byWorker&&!byEmployer)return;const shift=nextShiftDate(job);if(shift-Date.now()<CANCELLATION_CUTOFF_MS){document.querySelector('#cancellationModal').close();return toast('Minął termin anulowania online: wymagane jest minimum 8 godzin przed zmianą.')}const hoursBefore=Math.max(0,(shift-Date.now())/3600000),entry={id:`cancel-${jobId}-${Date.now()}`,jobId,applicationId:app.id,workerEmail:app.workerEmail,workerName:app.workerName,cancelledBy,reason:form.reason.value,details:form.details.value.trim(),cancelledAt:Date.now(),hoursBefore,late:hoursBefore<24};cancellations.push(entry);localStorage.setItem('flexo-cancellations',JSON.stringify(cancellations));if(byWorker){app.status='worker_cancelled';booked=booked.filter(id=>id!==jobId);localStorage.setItem('flexo-booked',JSON.stringify(booked));saveApplications()}else{app.status='employer_cancelled';job.active=false;job.cancelledByEmployer=true;job.cancellationReason=entry.reason;saveApplications();localStorage.setItem('flexo-jobs',JSON.stringify(jobs))}document.querySelector('#cancellationModal').close();renderJobs();renderBooked();renderAdminJobs();renderWorkerNotifications();if(jobsMap)updateMap();toast(byWorker?'Rezygnacja zapisana. Oferta znów jest dostępna dla innych.':'Zmiana anulowana. Pracownik otrzyma informację.')}
function setupCancellationWorkflow(){const modal=document.createElement('dialog');modal.id='cancellationModal';modal.className='cancellation-modal';modal.innerHTML=`<button class="modal-close" aria-label="Zamknij">×</button><form id="cancellationForm" class="cancellation-form"><input type="hidden" name="jobId"><input type="hidden" name="cancelledBy"><p class="eyebrow">ANULOWANIE POTWIERDZONEJ ZMIANY</p><h2 data-cancel-title></h2><p class="review-job" data-cancel-job></p><div class="cancellation-warning" data-cancel-warning></div><label>Powód rezygnacji<select name="reason" required><option value="">Wybierz powód</option><option value="health">Choroba lub nagła sytuacja zdrowotna</option><option value="family">Pilna sytuacja rodzinna</option><option value="schedule">Zmiana planów lub kolizja terminów</option><option value="operational">Zmiana potrzeb operacyjnych firmy</option><option value="other">Inny powód</option></select></label><label>Dodatkowa informacja (opcjonalnie)<textarea name="details" rows="3" maxlength="300" placeholder="Krótko wyjaśnij sytuację drugiej stronie"></textarea></label><p class="review-note">Anulowanie jest możliwe do rozpoczęcia zmiany. Powtarzające się lub późne rezygnacje mogą wpływać na wiarygodność konta.</p><button class="cancel-shift-confirm" type="submit">Potwierdzam anulowanie zmiany</button></form>`;document.body.appendChild(modal);modal.querySelector('.modal-close').onclick=()=>modal.close();modal.querySelector('form').onsubmit=e=>{e.preventDefault();submitCancellation(e.target)}}
function renderWorkerNotifications(){expireApplications();const box=document.querySelector('#workerNotifications');if(!box)return;if(authUser?.role!=='user'){box.hidden=true;return}const mine=applications.filter(a=>a.workerEmail===authUser.email).sort((a,b)=>b.appliedAt-a.appliedAt);box.hidden=!mine.length;box.innerHTML=mine.map(a=>{const j=jobs.find(x=>x.id===a.jobId);if(!j)return'';const texts={pending:['Oczekuje na potwierdzenie',`Pracodawca wybiera kandydata · pozostało <b data-deadline="${a.deadline}">${remainingTime(a.deadline)}</b>`],confirmed:['Zlecenie potwierdzone ✓','Pracodawca wybrał Ciebie. Zmiana jest w Twoim kalendarzu.'],completed:['Zmiana wykonana i oceniona ✓','Ocena pracodawcy została doliczona do średniej w Twoim profilu.'],rejected:['Wybrano inną osobę','Tym razem pracodawca wybrał innego kandydata. Może następnym razem!'],expired:['Brak decyzji w wymaganym czasie','Zgłoszenie wygasło — możesz wybrać inną zmianę.']}[a.status];return`<article class="application-notice ${a.status}"><span>${['confirmed','completed'].includes(a.status)?'✓':a.status==='pending'?'◷':'i'}</span><div><small>${j.role} · ${j.company}</small><strong>${texts[0]}</strong><p>${texts[1]}</p></div>${['confirmed','completed'].includes(a.status)?`<button onclick="openJob(${j.id})">Szczegóły</button>`:''}</article>`}).join('')}
