function decorateManagementCancellations(){document.querySelectorAll('.admin-job-row').forEach(row=>{const candidateButton=row.querySelector('.candidates-action'),match=candidateButton?.getAttribute('onclick')?.match(/\((\d+)\)/);if(!match)return;const jobId=+match[1],job=jobs.find(j=>j.id===jobId),app=applications.find(a=>a.jobId===jobId&&a.status==='confirmed'),last=latestCancellation(jobId),status=row.querySelector(':scope > .status'),actions=row.querySelector('.admin-actions');if(job?.cancelledByEmployer&&status){status.className='status cancelled';status.textContent='Anulowana przez pracodawcę'}else if(last?.cancelledBy==='worker'&&!app&&status){status.className='status reopened';status.textContent='Pracownik zrezygnował · ponownie dostępna'}if(app&&actions&&!actions.querySelector('.cancel-action'))actions.insertAdjacentHTML('afterbegin',`<button class="cancel-action" onclick="openCancellation(${jobId})" title="Anuluj potwierdzoną zmianę">↩</button>`)})}
