const openJobCancellationBase=openJob;openJob=function(id){openJobCancellationBase(id);if(authUser?.role!=='user')return;const app=myApplication(id),body=jobModal.querySelector('.modal-body');if(!app||!body)return;if(app.status==='confirmed'&&!body.querySelector('.cancel-shift-button')){const notice=body.querySelector('.details-notice');notice?.insertAdjacentHTML('beforebegin',`<button class="cancel-shift-button" onclick="openCancellation(${id})">Nie mogę przyjść — anuluj zmianę</button>`)}if(['worker_cancelled','employer_cancelled'].includes(app.status)){const button=body.querySelector('.book-button'),state=body.querySelector('.application-state');if(button){button.textContent=app.status==='worker_cancelled'?'Zrezygnowałeś z tej zmiany':'Zmiana anulowana przez pracodawcę';button.disabled=true}if(state)state.innerHTML=`<strong>${applicationStatusText(app.status)}</strong><p>${app.status==='worker_cancelled'?'Oferta wróciła na rynek dla innych pracowników.':'Termin został zwolniony w Twoim kalendarzu.'}</p>`}}
function setupEmployerIssueWorkflow(){const modal=document.createElement('dialog');modal.id='employerIssueModal';modal.className='cancellation-modal employer-issue-modal';modal.innerHTML=`<button class="modal-close" aria-label="Zamknij">×</button><form id="employerIssueForm" class="cancellation-form"><input type="hidden" name="jobId"><p class="eyebrow">PROBLEM NA MIEJSCU PRACY</p><h2>Warunki różnią się od oferty?</h2><p class="review-job" data-issue-job></p><div class="cancellation-warning"><strong>Nie rozpoczynaj pracy bez uzgodnionej umowy.</strong> Takie zgłoszenie nie jest zwykłą rezygnacją pracownika. Sprawa trafi do administratora, a prowizja Flexo pozostanie naliczona pracodawcy.</div><label>Co się wydarzyło?<select name="reason" required><option value="">Wybierz problem</option><option value="contract_type">Zaproponowano inny rodzaj umowy</option><option value="pay">Wynagrodzenie jest inne niż w ofercie</option><option value="duties">Obowiązki lub godziny są inne</option><option value="no_contract">Pracodawca odmawia podpisania umowy</option><option value="other_terms">Umowa zawiera inne nieuzgodnione warunki</option><option value="safety">Warunki są niebezpieczne lub nielegalne</option><option value="other">Inny poważny problem</option></select></label><label>Opisz sytuację<textarea name="details" rows="4" minlength="10" maxlength="700" required placeholder="Napisz, co było inne niż w ofercie i z kim rozmawiałeś/aś"></textarea></label><label class="terms-check"><input name="arrived" type="checkbox" required><span>Potwierdzam, że dotarłem/am na miejsce wskazane w ofercie.</span></label><p class="review-note">Zachowaj zdjęcie miejsca, wiadomości lub dokument przedstawiony do podpisu. Administrator może poprosić obie strony o wyjaśnienia.</p><button class="cancel-shift-confirm" type="submit">Zgłoś problem i zrezygnuj bez kary</button></form>`;document.body.appendChild(modal);modal.querySelector('.modal-close').onclick=()=>modal.close();modal.querySelector('form').onsubmit=e=>{e.preventDefault();submitEmployerIssue(e.target)}}
function openEmployerIssue(jobId){const job=jobs.find(j=>j.id===jobId),app=applications.find(a=>a.jobId===jobId&&a.workerEmail===authUser?.email&&a.status==='confirmed');if(!job||!app)return toast('To zgłoszenie jest dostępne tylko dla potwierdzonej zmiany.');const form=document.querySelector('#employerIssueForm');form.reset();form.jobId.value=jobId;form.querySelector('[data-issue-job]').textContent=`${job.role} · ${job.company} · ${job.date}, ${job.time}`;document.querySelector('#jobModal')?.close();document.querySelector('#employerIssueModal').showModal()}
function submitEmployerIssue(form){const jobId=+form.jobId.value,app=applications.find(a=>a.jobId===jobId&&a.workerEmail===authUser?.email&&a.status==='confirmed'),job=jobs.find(j=>j.id===jobId);if(!app||!job)return;const report={id:`issue-${jobId}-${Date.now()}`,jobId,applicationId:app.id,workerEmail:app.workerEmail,workerName:app.workerName,employerEmail:job.ownerEmail,reason:form.reason.value,details:form.details.value.trim(),arrived:true,status:'pending_review',feeRetained:true,createdAt:Date.now()};employerIssueReports.push(report);localStorage.setItem('flexo-employer-issue-reports',JSON.stringify(employerIssueReports));app.status='employer_issue';saveApplications();booked=booked.filter(id=>id!==jobId);localStorage.setItem('flexo-booked',JSON.stringify(booked));document.querySelector('#employerIssueModal').close();renderJobs();renderBooked();renderAdminJobs();renderWorkerNotifications();toast('Zgłoszenie zapisane. Nie ponosisz kary, a sprawa trafiła do administratora.')}
function employerIssueFor(jobId,email){return employerIssueReports.find(r=>r.jobId===jobId&&(!email||r.workerEmail===email))}
const openJobBeforeEmployerIssue=openJob;openJob=function(id){openJobBeforeEmployerIssue(id);if(authUser?.role!=='user')return;const app=myApplication(id),body=jobModal.querySelector('.modal-body');if(!app||!body)return;if(app.status==='confirmed'&&!body.querySelector('.employer-issue-button'))body.insertAdjacentHTML('beforeend',`<button class="employer-issue-button" onclick="openEmployerIssue(${id})">Warunki na miejscu są inne — zgłoś problem</button>`);if(app.status==='employer_issue'){body.querySelector('.book-button')?.remove();body.querySelector('.cancel-shift-button')?.remove();body.insertAdjacentHTML('beforeend','<div class="issue-submitted-note"><strong>⚠ Problem zgłoszony do Flexo</strong><p>Nie musisz podejmować pracy na zmienionych warunkach. Zgłoszenie nie obciąża Twojego konta.</p></div>')}}
