function openAdminIssue(jobId){const report=employerIssueFor(jobId),job=jobs.find(j=>j.id===jobId);if(authUser?.role!=='admin'||!report||!job)return;const labels={contract_type:'Inny rodzaj umowy',pay:'Inne wynagrodzenie',duties:'Inne obowiązki lub godziny',no_contract:'Odmowa podpisania umowy',other_terms:'Inne warunki w umowie',safety:'Warunki niebezpieczne lub nielegalne',other:'Inny problem'};showAdminDetails(`<div class="admin-detail-head"><div class="avatar large issue-avatar">!</div><div><p class="eyebrow">ZGŁOSZENIE PRACOWNIKA</p><h2>${job.role} · ${job.company}</h2><span class="status employer-issue-status">Do wyjaśnienia</span></div></div><div class="admin-detail-grid"><div><small>PRACOWNIK</small><strong>${report.workerName}</strong></div><div><small>PRACODAWCA</small><strong>${job.company}</strong></div><div><small>POWÓD</small><strong>${labels[report.reason]||report.reason}</strong></div><div><small>PROWIZJA</small><strong>${jobBilling(job).fee} zł · pozostaje naliczona</strong></div></div><div class="issue-report-details"><h3>Opis pracownika</h3><p>${report.details.replace(/[<>]/g,'')}</p><small>Pracownik potwierdził dotarcie na miejsce. Zgłoszenie wymaga kontaktu z obiema stronami.</small></div>`)}
function checkinStartDate(job){const dayNumbers={monday:1,tuesday:2,wednesday:3,thursday:4,friday:5,saturday:6,sunday:0},now=new Date(),date=new Date(now),target=dayNumbers[job.day]??now.getDay();date.setDate(now.getDate()+((target-now.getDay()+7)%7));date.setHours(Math.floor(job.start),Math.round(job.start%1*60),0,0);if(date<new Date(now.getTime()-60*60*1000))date.setDate(date.getDate()+7);return date}
function hasArrivalCheckin(jobId,email=authUser?.email){return arrivalCheckins.some(c=>c.jobId===jobId&&c.workerEmail===email)}
function openArrivalCheckin(jobId,demo=false){const job=jobs.find(j=>j.id===jobId);if(!job)return;const d=getJobDetails(job),modal=document.querySelector('#arrivalCheckinModal'),form=modal.querySelector('form');form.jobId.value=jobId;form.dataset.demo=demo?'true':'false';modal.querySelector('[data-checkin-job]').textContent=`${job.role} · ${job.company}`;modal.querySelector('[data-checkin-time]').textContent=`${job.date}, ${job.time}`;modal.querySelector('[data-checkin-address]').textContent=d.address;modal.querySelector('.checkin-demo-note').hidden=!demo;modal.showModal()}
function confirmArrivalCheckin(form){const jobId=+form.jobId.value,job=jobs.find(j=>j.id===jobId);if(!job)return;if(form.dataset.demo==='true'){document.querySelector('#arrivalCheckinModal').close();return toast('Tak wygląda potwierdzenie przybycia. W trybie testowym nic nie zapisaliśmy.')}if(hasArrivalCheckin(jobId)){document.querySelector('#arrivalCheckinModal').close();return}arrivalCheckins.push({id:`checkin-${jobId}-${Date.now()}`,jobId,workerEmail:authUser.email,checkedInAt:Date.now(),status:'arrived'});localStorage.setItem('flexo-arrival-checkins',JSON.stringify(arrivalCheckins));document.querySelector('#arrivalCheckinModal').close();renderWorkerNotifications();toast('Przybycie potwierdzone. Zapisaliśmy godzinę check-inu.')}
function checkDueArrival(){if(authUser?.role!=='user'||document.querySelector('#arrivalCheckinModal')?.open)return;const now=Date.now(),app=applications.find(a=>a.workerEmail===authUser.email&&a.status==='confirmed'&&!hasArrivalCheckin(a.jobId)&&(()=>{const job=jobs.find(j=>j.id===a.jobId);if(!job)return false;const start=checkinStartDate(job).getTime();return now>=start-15*60*1000&&now<=start+60*60*1000})());if(!app)return;const promptKey=`flexo-checkin-prompt-${app.jobId}-${new Date().toDateString()}`,snoozedUntil=+(sessionStorage.getItem(promptKey)||0);if(snoozedUntil>now)return;sessionStorage.setItem(promptKey,String(now+5*60*1000));openArrivalCheckin(app.jobId)}
function setupArrivalCheckin(){const modal=document.createElement('dialog');modal.id='arrivalCheckinModal';modal.className='arrival-checkin-modal';modal.innerHTML=`<button class="modal-close" aria-label="Zamknij">×</button><form class="arrival-checkin-form"><input type="hidden" name="jobId"><div class="checkin-icon">⌖</div><p class="eyebrow">CHECK-IN PRZED ZMIANĄ</p><h2>Jesteś już na miejscu?</h2><strong data-checkin-job></strong><p data-checkin-time></p><div class="checkin-address"><small>ADRES ZMIANY</small><b data-checkin-address></b></div><p>Potwierdzenie zapisze godzinę przybycia. Nie pobieramy Twojej lokalizacji.</p><div class="checkin-demo-note" hidden>To jest podgląd demonstracyjny — potwierdzenie nie zostanie zapisane.</div><button type="submit" class="checkin-confirm">Tak, jestem na miejscu</button><button type="button" class="checkin-later">Jeszcze nie — przypomnij za 5 minut</button></form>`;document.body.appendChild(modal);modal.querySelector('.modal-close').onclick=()=>modal.close();modal.querySelector('.checkin-later').onclick=()=>modal.close();modal.querySelector('form').onsubmit=e=>{e.preventDefault();confirmArrivalCheckin(e.target)};const demo=document.createElement('button');demo.type='button';demo.className='checkin-demo-button';demo.textContent='Podejrzyj check-in przed zmianą';demo.onclick=()=>{const confirmed=applications.find(a=>a.workerEmail===authUser?.email&&a.status==='confirmed'),job=jobs.find(j=>j.id===(confirmed?.jobId||jobs[0]?.id));if(job)openArrivalCheckin(job.id,true)};document.querySelector('#profile .checklist')?.appendChild(demo);setInterval(checkDueArrival,30000);setTimeout(checkDueArrival,1200)}
const openJobBeforeCheckin=openJob;openJob=function(id){openJobBeforeCheckin(id);if(authUser?.role!=='user'||!hasArrivalCheckin(id))return;const body=jobModal.querySelector('.modal-body'),entry=arrivalCheckins.find(c=>c.jobId===id&&c.workerEmail===authUser.email);body?.insertAdjacentHTML('afterbegin',`<div class="checkin-success-note"><strong>✓ Przybycie potwierdzone</strong><span>${new Date(entry.checkedInAt).toLocaleTimeString(currentLanguage==='en'?'en-GB':'pl-PL',{hour:'2-digit',minute:'2-digit'})}</span></div>`)}
const openJobBeforeCancellationPolicy=openJob;openJob=function(id){openJobBeforeCancellationPolicy(id);const job=jobs.find(j=>j.id===id),body=jobModal.querySelector('.modal-body');if(!job||!body||body.querySelector('.cancellation-policy-note'))return;const policy=cancellationPolicyFor(job),app=myApplication(id),locked=policy.adHoc||app?.cancellationPolicy==='ad_hoc_locked';body.insertAdjacentHTML('afterbegin',locked?'<div class="cancellation-policy-note locked"><strong>⚡ Zlecenie ad hoc</strong><p>Start za mniej niż 8 godzin. Po zaakceptowaniu kandydata żadna ze stron nie może odwołać zmiany. Zgłoś się tylko wtedy, gdy masz pewność, że możesz przyjść.</p></div>':'<div class="cancellation-policy-note standard"><strong>↩ Elastyczne anulowanie</strong><p>Po zaakceptowaniu kandydatury pracownik i pracodawca mogą zrezygnować najpóźniej 8 godzin przed rozpoczęciem zmiany.</p></div>');if(locked&&authUser?.role==='user'&&!app){const button=body.querySelector('.book-button');if(button)button.textContent='Zgłaszam się — bez możliwości anulowania'}}
const renderAdminJobsBeforeCancellationPolicy=renderAdminJobs;renderAdminJobs=function(){renderAdminJobsBeforeCancellationPolicy();document.querySelectorAll('.admin-job-row').forEach(row=>{const action=row.querySelector('.preview-action'),id=+(action?.getAttribute('onclick')?.match(/\((\d+)\)/)?.[1]||0),job=jobs.find(j=>j.id===id);if(!job||!cancellationPolicyFor(job).adHoc)return;row.querySelector('.cancel-action')?.remove();const summary=row.querySelector('div>small');if(summary&&!summary.querySelector?.('.ad-hoc-label'))summary.insertAdjacentHTML('beforeend',' <b class="ad-hoc-label">· AD HOC · brak anulowania</b>')})}
